CREATE OR REPLACE FUNCTION public.create_thread(p_subject_type text, p_subject_id bigint DEFAULT NULL::bigint, p_participant_member_ids bigint[] DEFAULT '{}'::bigint[], p_visibility text DEFAULT NULL::text)
 RETURNS public.threads
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account_id bigint;
  v_member_id bigint;
  v_visibility text;
  v_thread public.threads;
  v_participant_id bigint;
begin
  v_account_id := public.current_context_id();
  if v_account_id is null then
    raise exception 'no account context for create_thread (no account exists)';
  end if;

  v_member_id := public.current_member_id();
  if v_member_id is null then
    raise exception 'no active membership for create_thread';
  end if;

  if p_subject_type not in ('shidduch', 'relationship') then
    raise exception 'invalid thread subject_type: %', p_subject_type
      using errcode = 'check_violation';
  end if;

  -- Never cross the account boundary (AD-1): the subject shidduch must
  -- belong to the caller's account, and must actually exist.
  if p_subject_type = 'shidduch' and not exists (
    select 1 from public.shidduchim where id = p_subject_id and account_id = v_account_id
  ) then
    raise exception 'shidduch % not found in current account', p_subject_id;
  end if;

  v_visibility := coalesce(p_visibility, 'open');
  if v_visibility not in ('open', 'private') then
    raise exception 'invalid thread visibility: %', v_visibility
      using errcode = 'check_violation';
  end if;

  insert into public.threads (
    account_id, connection_id, subject_type, subject_id, visibility, created_by_member_id
  ) values (
    v_account_id, null,
    p_subject_type,
    case when p_subject_type = 'shidduch' then p_subject_id else null end,
    v_visibility, v_member_id
  )
  returning * into v_thread;

  -- The creator is always a participant, from the moment the thread exists
  -- (AC-2).
  insert into public.thread_participants (account_id, connection_id, thread_id, member_id)
  values (v_account_id, null, v_thread.id, v_member_id);

  -- One row per DISTINCT supplied id (AC-7). Fail fast on any id that is
  -- not an active account_members row of the caller's own account — never
  -- let a caller believe someone is in a conversation who silently was
  -- not added (.claude/rules/coding-style.md). ON CONFLICT DO NOTHING
  -- (thread_participants_thread_id_member_id_key) absorbs a duplicate in
  -- the array, or the caller's own id repeated, without a second check.
  foreach v_participant_id in array coalesce(p_participant_member_ids, '{}') loop
    if not exists (
      select 1 from public.account_members
      where id = v_participant_id and account_id = v_account_id and status = 'active'
    ) then
      raise exception 'member % not found in current account', v_participant_id;
    end if;
    insert into public.thread_participants (account_id, connection_id, thread_id, member_id)
    values (v_account_id, null, v_thread.id, v_participant_id)
    on conflict (thread_id, member_id) do nothing;
  end loop;

  return v_thread;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enforce_connection_kinds()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_household_kind text;
  v_shadchanus_kind text;
begin
  select kind into v_household_kind from public.accounts where id = new.household_account_id;
  select kind into v_shadchanus_kind from public.accounts where id = new.shadchanus_account_id;

  if v_household_kind is distinct from 'household' then
    raise exception 'connections.household_account_id % is not a household-kind account', new.household_account_id
      using errcode = 'check_violation';
  end if;

  if v_shadchanus_kind is distinct from 'shadchanus' then
    raise exception 'connections.shadchanus_account_id % is not a shadchanus-kind account', new.shadchanus_account_id
      using errcode = 'check_violation';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_message_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_account_id bigint;
  v_connection_id bigint;
begin
  if new.account_id is null and new.connection_id is null then
    select t.account_id, t.connection_id into v_account_id, v_connection_id
    from public.threads t where t.id = new.thread_id;
    new.account_id := v_account_id;
    new.connection_id := v_connection_id;
  end if;
  new.sender_member_id := public.current_member_id();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_thread_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.account_id is null and new.connection_id is null then
    new.account_id := public.current_context_id();
  end if;
  new.created_by_member_id := public.current_member_id();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_thread_participant_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_account_id bigint;
  v_connection_id bigint;
begin
  if new.account_id is null and new.connection_id is null then
    select t.account_id, t.connection_id into v_account_id, v_connection_id
    from public.threads t where t.id = new.thread_id;
    new.account_id := v_account_id;
    new.connection_id := v_connection_id;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.thread_is_readable(p_thread_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_thread public.threads;
begin
  select * into v_thread from public.threads where id = p_thread_id;
  if not found then
    return false;
  end if;

  -- The connection axis is unreachable to `authenticated` until Story 7.4
  -- opens it — failing closed here means 7.4 is a pure widening with
  -- nothing to un-leak.
  if v_thread.connection_id is not null then
    return false;
  end if;

  -- `is distinct from`, not `<>`: a NULL current_context_id() (no active
  -- context) must deny, not silently fall through to `true` the way a
  -- NULL-yielding `<>` comparison would inside an `if`.
  if v_thread.account_id is distinct from public.current_context_id() then
    return false;
  end if;

  if v_thread.subject_type = 'shidduch' and public.current_member_role() = 'single' then
    return exists (
      select 1
      from public.shidduchim s
      where s.id = v_thread.subject_id
        and s.visibility = 'shared'
        and public.is_single_visible_state(s.pipeline_state)
        and exists (
          select 1 from public.singles c
          where c.id = s.single_id and c.member_id = public.current_member_id()
        )
    );
  end if;

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.purge_polymorphic_dependents()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_target_type text := TG_ARGV[0];
begin
  delete from public.identity_signals
  where account_id = old.account_id and target_type = v_target_type and target_id = old.id;

  delete from public.interactions
  where account_id = old.account_id and target_type = v_target_type and target_id = old.id;

  delete from public.tasks
  where account_id = old.account_id and target_type = v_target_type and target_id = old.id;

  delete from public.entity_files
  where account_id = old.account_id and target_type = v_target_type and target_id = old.id;

  -- Story 7.1 (AC-10): a deleted shidduch takes its threads with it, on
  -- BOTH scope axes. thread_participants/messages cascade from this delete
  -- via their own composite FKs to threads (01_tables.sql) — no separate
  -- delete needed for them. An account_id = old.account_id predicate alone
  -- would miss a connection-scoped thread about the same subject (its
  -- account_id is NULL), leaving a shadchan holding a conversation about a
  -- deleted shidduch, pointing at a dangling subject — hence the exists()
  -- arm walking the connection back to old.account_id. v_target_type is
  -- 'reference'/'single'/'shadchan' for the other three callers of this
  -- function; none of those ever matches a thread's subject_type
  -- ('shidduch'/'relationship'), so this delete is a no-op for them.
  delete from public.threads t
  where t.subject_type = v_target_type
    and t.subject_id = old.id
    and (
      t.account_id = old.account_id
      or exists (
        select 1 from public.connections c
        where c.id = t.connection_id
          and c.household_account_id = old.account_id
      )
    );

  return old;
end;
$function$
;

-- Hand-added below each `db diff`-generated block: `db diff` emits only the
-- POSITIVE grants it finds in the shadow database's final privilege state;
-- it never emits a REVOKE, and Postgres's own default privileges (verified
-- on the local stack: `select grantee, privilege_type from
-- information_schema.role_table_grants where table_name = '_scratch'` on a
-- throwaway table) hand every NEW table's `authenticated`/`service_role`
-- TRUNCATE/REFERENCES/TRIGGER automatically at CREATE TABLE time — TRUNCATE
-- bypasses RLS, so leaving it ungranted on `authenticated` is not optional.
-- Function EXECUTE defaults to PUBLIC on every new function for the same
-- reason `db diff` still requires hand-inspection here.
revoke all on table "public"."connections" from "anon", "authenticated";
grant select on table "public"."connections" to "authenticated";
grant all on table "public"."connections" to "service_role";

revoke all on table "public"."messages" from "anon", "authenticated";
grant select, insert on table "public"."messages" to "authenticated";
grant all on table "public"."messages" to "service_role";

revoke all on table "public"."thread_participants" from "anon", "authenticated";
grant select, insert on table "public"."thread_participants" to "authenticated";
grant all on table "public"."thread_participants" to "service_role";

-- Review fix (Story 7.1 F2/F4): no INSERT grant on threads for
-- `authenticated` — see the policy drop below.
revoke all on table "public"."threads" from "anon", "authenticated";
grant select on table "public"."threads" to "authenticated";
grant all on table "public"."threads" to "service_role";

-- Hand-added: `db diff` emitted no sequence DDL at all for the four new
-- identity-column sequences. No `authenticated` grant on connections'
-- sequence — `authenticated` cannot insert into connections at all (no
-- INSERT policy, no INSERT grant above).
revoke all on sequence "public"."connections_id_seq" from "anon", "authenticated";
grant all on sequence "public"."connections_id_seq" to "service_role";

-- Review fix (Story 7.1 F2): no `authenticated` grant on threads_id_seq
-- either, mirroring connections_id_seq above — `authenticated` cannot
-- insert into threads at all as of this fix.
revoke all on sequence "public"."threads_id_seq" from "anon", "authenticated";
grant all on sequence "public"."threads_id_seq" to "service_role";

revoke all on sequence "public"."thread_participants_id_seq" from "anon";
grant usage, select on sequence "public"."thread_participants_id_seq" to "authenticated";
grant all on sequence "public"."thread_participants_id_seq" to "service_role";

revoke all on sequence "public"."messages_id_seq" from "anon";
grant usage, select on sequence "public"."messages_id_seq" to "authenticated";
grant all on sequence "public"."messages_id_seq" to "service_role";

-- Hand-added: `db diff` emitted no function-grant DDL at all for either new
-- function — `thread_is_readable` is SECURITY DEFINER and would otherwise
-- keep Postgres's default PUBLIC EXECUTE grant.
revoke all on function "public"."thread_is_readable"(bigint) from "public", "anon";
grant execute on function "public"."thread_is_readable"(bigint) to "authenticated";
grant execute on function "public"."thread_is_readable"(bigint) to "service_role";

revoke all on function "public"."create_thread"(text, bigint, bigint[], text) from "public", "anon";
grant execute on function "public"."create_thread"(text, bigint, bigint[], text) to "authenticated";
grant execute on function "public"."create_thread"(text, bigint, bigint[], text) to "service_role";


  create policy "Connections visible to either side"
  on "public"."connections"
  as permissive
  for select
  to authenticated
using (((household_account_id = public.current_context_id()) OR (shadchanus_account_id = public.current_context_id())));



  create policy "Messages insertable by an existing participant"
  on "public"."messages"
  as permissive
  for insert
  to authenticated
with check (((account_id = public.current_context_id()) AND (connection_id IS NULL) AND (EXISTS ( SELECT 1
   FROM public.thread_participants tp
  WHERE ((tp.thread_id = messages.thread_id) AND (tp.member_id = public.current_member_id()))))));



  create policy "Messages readable per thread_is_readable"
  on "public"."messages"
  as permissive
  for select
  to authenticated
using (public.thread_is_readable(thread_id));



  create policy "Thread participants insertable by an existing participant"
  on "public"."thread_participants"
  as permissive
  for insert
  to authenticated
with check (((account_id = public.current_context_id()) AND (connection_id IS NULL) AND (EXISTS ( SELECT 1
   FROM public.thread_participants tp
  WHERE ((tp.thread_id = thread_participants.thread_id) AND (tp.member_id = public.current_member_id())))) AND (EXISTS ( SELECT 1
   FROM public.account_members am
  WHERE ((am.id = thread_participants.member_id) AND (am.account_id = public.current_context_id()) AND (am.status = 'active'::text))))));



  create policy "Thread participants readable per thread_is_readable"
  on "public"."thread_participants"
  as permissive
  for select
  to authenticated
using (public.thread_is_readable(thread_id));



-- Review fix (Story 7.1 F2/F4): "Threads insertable account-scoped only"
-- dropped entirely — no INSERT policy and no INSERT grant (above) for
-- `authenticated` on threads, matching the `connections` bare pattern. See
-- 05_policies.sql for the full account of what this policy failed to
-- enforce (AC-1 subject reachability) and why it was already unusable for
-- a real PostgREST INSERT...RETURNING.


  create policy "Threads readable per thread_is_readable"
  on "public"."threads"
  as permissive
  for select
  to authenticated
using (public.thread_is_readable(id));


CREATE TRIGGER validate_connections_kinds BEFORE INSERT OR UPDATE ON public.connections FOR EACH ROW EXECUTE FUNCTION public.enforce_connection_kinds();

CREATE TRIGGER set_messages_defaults BEFORE INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.set_message_defaults();

CREATE TRIGGER set_thread_participants_defaults BEFORE INSERT ON public.thread_participants FOR EACH ROW EXECUTE FUNCTION public.set_thread_participant_defaults();

CREATE TRIGGER set_threads_defaults BEFORE INSERT ON public.threads FOR EACH ROW EXECUTE FUNCTION public.set_thread_defaults();


